static int /* <=== remote_match */ 
remote_match (pam_handle_t *pamh, char *tok, struct login_info *item)
{
    const char *string = item->from;
    size_t tok_len = strlen(tok);
    size_t str_len;

    if (tok[0] == '.') {			/* domain: match last fields */
      if ((str_len = strlen(string)) > tok_len
	  && strcasecmp(tok, string + str_len - tok_len) == 0)
	return YES;
    } else if (tok[tok_len - 1] == '.') {       /* internet network numbers (end with ".") */
      struct addrinfo hint;

      memset (&hint, '\0', sizeof (hint));
      hint.ai_flags = AI_CANONNAME;
      hint.ai_family = AF_INET;

      if (item->gai_rv != 0)
	return NO;
      else if (!item->res &&
		(item->gai_rv = getaddrinfo (string, NULL, &hint, &item->res)) != 0)
	return NO;
      else
	{
	  struct addrinfo *runp = item->res;

          while (runp != NULL)
	    {
	      char buf[INET_ADDRSTRLEN+2];

	      if (runp->ai_family == AF_INET)
		{
		  DIAG_PUSH_IGNORE_CAST_ALIGN;
		  inet_ntop (runp->ai_family,
			     &((struct sockaddr_in *) runp->ai_addr)->sin_addr,
			     buf, sizeof (buf));
		  DIAG_POP_IGNORE_CAST_ALIGN;

		  strcat (buf, ".");

		  if (strncmp(tok, buf, tok_len) == 0)
		    {
		      return YES;
		    }
		}
	      runp = runp->ai_next;
	    }
	}
      return NO;
    }

    /* Assume network/netmask, IP address or hostname.  */
    return network_netmask_match(pamh, tok, string, item);
}

static int /* <=== string_match */ 
string_match (pam_handle_t *pamh, const char *tok, const char *string,
    int debug)
{

    if (debug)
        pam_syslog (pamh, LOG_DEBUG,
		    "string_match: tok=%s, item=%s", tok, string);

    /*
     * If the token has the magic value "ALL" the match always succeeds.
     * Otherwise, return YES if the token fully matches the string.
     * "NONE" token matches NULL string.
     */

    if (strcasecmp(tok, "ALL") == 0) {		/* all: always matches */
	return (ALL);
    } else if (string != NULL) {
	if (strcasecmp(tok, string) == 0) {	/* try exact match */
	    return (YES);
	}
    } else if (strcasecmp(tok, "NONE") == 0) {
	return (YES);
    }
    return (NO);
}

static int /* <=== network_netmask_match */ 
network_netmask_match (pam_handle_t *pamh,
		       const char *tok, const char *string, struct login_info *item)
{
    char *netmask_ptr;
    char netmask_string[MAXHOSTNAMELEN + 1];
    int addr_type;
    struct addrinfo *ai = NULL;

    if (item->debug)
      pam_syslog (pamh, LOG_DEBUG,
		"network_netmask_match: tok=%s, item=%s", tok, string);

    /* OK, check if tok is of type addr/mask */
    if ((netmask_ptr = strchr(tok, '/')) != NULL)
      {
	long netmask = 0;

	/* YES */
	*netmask_ptr = 0;
	netmask_ptr++;

	if (isipaddr(tok, &addr_type, NULL) == NO)
	  { /* no netaddr */
	    return NO;
	  }

	/* check netmask */
	if (isipaddr(netmask_ptr, NULL, NULL) == NO)
	  { /* netmask as integre value */
	    char *endptr = NULL;
	    netmask = strtol(netmask_ptr, &endptr, 0);
	    if ((endptr == netmask_ptr) || (*endptr != '\0'))
		{ /* invalid netmask value */
		  return NO;
		}
	    if ((netmask < 0)
		|| (addr_type == AF_INET && netmask > 32)
		|| (addr_type == AF_INET6 && netmask > 128))
		{ /* netmask value out of range */
		  return NO;
		}

	    netmask_ptr = number_to_netmask(netmask, addr_type,
		netmask_string, MAXHOSTNAMELEN);
	  }

        /*
         * Construct an addrinfo list from the IP address.
         * This should not fail as the input is a correct IP address...
         */
	if (getaddrinfo (tok, NULL, NULL, &ai) != 0)
	  {
	    return NO;
	  }
      }
    else
      {
        /*
	 * It is either an IP address or a hostname.
	 * Let getaddrinfo sort everything out
	 */
	if (getaddrinfo (tok, NULL, NULL, &ai) != 0)
	  {
	    pam_syslog(pamh, LOG_ERR, "cannot resolve hostname \"%s\"", tok);

	    return NO;
	  }
	netmask_ptr = NULL;
      }

    if (isipaddr(string, NULL, NULL) != YES)
      {
	struct addrinfo hint;

	/* Assume network/netmask with a name of a host.  */
	memset (&hint, '\0', sizeof (hint));
	hint.ai_flags = AI_CANONNAME;
	hint.ai_family = AF_UNSPEC;

	if (item->gai_rv != 0)
	  {
	    freeaddrinfo(ai);
	    return NO;
	  }
	else if (!item->res &&
		(item->gai_rv = getaddrinfo (string, NULL, &hint, &item->res)) != 0)
	  {
	    freeaddrinfo(ai);
	    return NO;
	  }
        else
	  {
	    struct addrinfo *runp = item->res;
	    struct addrinfo *runp1;

	    while (runp != NULL)
	      {
		char buf[INET6_ADDRSTRLEN];

		if (getnameinfo (runp->ai_addr, runp->ai_addrlen, buf, sizeof (buf), NULL, 0, NI_NUMERICHOST) != 0)
		  {
		    freeaddrinfo(ai);
		    return NO;
		  }

		for (runp1 = ai; runp1 != NULL; runp1 = runp1->ai_next)
		  {
                    char buf1[INET6_ADDRSTRLEN];

                    if (runp->ai_family != runp1->ai_family)
                      continue;

                    if (getnameinfo (runp1->ai_addr, runp1->ai_addrlen, buf1, sizeof (buf1), NULL, 0, NI_NUMERICHOST) != 0)
		      {
			freeaddrinfo(ai);
			return NO;
		      }

                    if (are_addresses_equal (buf, buf1, netmask_ptr))
                      {
                        freeaddrinfo(ai);
                        return YES;
                      }
		  }
		runp = runp->ai_next;
	      }
	  }
      }
    else
      {
       struct addrinfo *runp1;

       for (runp1 = ai; runp1 != NULL; runp1 = runp1->ai_next)
         {
           char buf1[INET6_ADDRSTRLEN];

           (void) getnameinfo (runp1->ai_addr, runp1->ai_addrlen, buf1, sizeof (buf1), NULL, 0, NI_NUMERICHOST);

           if (are_addresses_equal(string, buf1, netmask_ptr))
             {
               freeaddrinfo(ai);
               return YES;
             }
         }
      }

  freeaddrinfo(ai);

  return NO;
}

